// scripts/build-bundle.mjs
// Generates AGENT_PROMPT.md (from AGENT_PROMPT.template.md), ai-bundle.md,
// and examples/prototype/tokens.css from tokens.json + the source docs.
// Run via `npm run build`. Generated files are committed; CI fails on drift.
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { resolve, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { flatten } from './lib/color.mjs';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const read = (p) => readFileSync(resolve(root, p), 'utf8');
const tokens = JSON.parse(read('tokens.json'));
const version = tokens.version;

// Token table: the two theme palettes, by dot-path.
const themeColors = Object.fromEntries(
  Object.entries(flatten(tokens.themes)).filter(([, v]) => typeof v === 'string' && v.startsWith('#'))
);
const tokenTable = [
  '| Token | Value |',
  '| --- | --- |',
  ...Object.entries(themeColors).map(([k, v]) => `| \`themes.${k}\` | \`${v.toUpperCase()}\` |`),
].join('\n');

const prompt = read('AGENT_PROMPT.template.md').replace('{{TOKEN_TABLE}}', tokenTable);
writeFileSync(resolve(root, 'AGENT_PROMPT.md'), prompt);

const EXAMPLES = ['wireframe-utility', 'wireframe-exorsyst', 'wireframe-yttraydl', 'wireframe-safereturn', 'wireframe-roomforge'];
const bundle = [
  `# FluentGruv — AI Bundle (v${version})`,
  '',
  'The complete FluentGruv spec in one file: enforcement prompt, layout specification, tokens (dark + light), the machine-readable tokens.json, and every example wireframe. Generated by `npm run build` (`scripts/build-bundle.mjs`) from the individual files in this repository — if anything differs, the individual files win.',
  '',
  '---',
  '',
  prompt.trimEnd(),
  '',
  '---',
  '',
  read('SPEC.md').trimEnd(),
  '',
  '---',
  '',
  read('TOKENS.md').trimEnd(),
  '',
  '---',
  '',
  '# tokens.json (verbatim)',
  '',
  '```json',
  read('tokens.json').trimEnd(),
  '```',
  ...EXAMPLES.flatMap((name) => ['', '---', '', `# examples/${name}.txt (verbatim)`, '', '```text', read(`examples/${name}.txt`).trimEnd(), '```']),
  '',
].join('\n');
writeFileSync(resolve(root, 'ai-bundle.md'), bundle);

// CSS custom properties for the runnable prototype: dark on :root,
// light under [data-theme="light"].
const vars = (theme) =>
  Object.entries(flatten(tokens.themes[theme]))
    .filter(([, v]) => typeof v === 'string' && v.startsWith('#'))
    .map(([k, v]) => `  --${k.replace(/\./g, '-')}: ${v};`)
    .join('\n');
mkdirSync(resolve(root, 'examples/prototype'), { recursive: true });
writeFileSync(
  resolve(root, 'examples/prototype/tokens.css'),
  `/* GENERATED from tokens.json by npm run build — do not edit */\n:root {\n${vars('dark')}\n  --accent-focus: ${tokens.themes.dark.accent.primary};\n}\n[data-theme="light"] {\n${vars('light')}\n  --accent-focus: ${tokens.themes.light.accent.primary};\n}\n`
);

console.log(`Built AGENT_PROMPT.md, ai-bundle.md, tokens.css (${Object.keys(themeColors).length} theme colors, v${version}).`);
